INSERT INTO cms.review (id, author_en, author_ar, company_en, company_ar, quote_en, quote_ar, rating, is_approved, sort_order, year, created_at) VALUES ('f1301319-74d7-4e25-a4d1-0f534525723d', 'Eng. Salman Al-Moayyed', 'م. سلمان المؤيد', 'Almoayyed Contracting Group W.L.L.', 'مجموعة المؤيد للمقاولات ذ.م.م', 'Marina Heights consistently delivers on complex Bahrain commercial schedules with transparent VAT documentation and responsive bilingual account leads.', 'تلتزم مارينا هايتس دائماً بالجداول الزمنية للمشاريع التجارية في البحرين مع توثيق ضريبي شفاف وفريق حسابات سريع الاستجابة.', 5, true, 20, 2026, now() - interval '15 days') ON CONFLICT (id) DO NOTHING;
INSERT INTO cms.review (id, author_en, author_ar, company_en, company_ar, quote_en, quote_ar, rating, is_approved, sort_order, year, created_at) VALUES ('f5bedb56-8963-48bb-a498-5a70e29c265e', 'Dr. Hessa Al-Zayani', 'د. حصة الزياني', 'Dilmunia Health & Wellness Center', 'مركز دلمونيا للصحة والعافية', 'From initial quotation to final commissioning, the Marina Heights operations team exceeded our SLA expectations.', 'من عرض السعر الأولي حتى التسليم النهائي، تجاوز فريق عمليات مارينا هايتس توقعاتنا في الالتزام بمستوى الخدمة.', 5, true, 21, 2026, now() - interval '20 days') ON CONFLICT (id) DO NOTHING;
INSERT INTO cms.faq (id, question_en, question_ar, answer_en, answer_ar, category, is_published, sort_order, created_at) VALUES ('e3bd8a07-44c9-4d79-a659-eb2b52b5e1cf', 'Are all Marina Heights invoices compliant with Bahrain NBR 10% VAT regulations?', 'هل جميع فواتير مارينا هايتس متوافقة مع لوائح ضريبة القيمة المضافة 10% في البحرين؟', 'Yes. Every quotation and tax invoice includes our registered VAT ID (200012988000002), itemized tax calculations, and verifiable QR metadata.', 'نعم، تتضمن كل فاتورة ضريبية وعرض سعر رقمنا الضريبي المسجل (200012988000002) مع تفصيل الضريبة ورمز التحقق.', 'billing', true, 20, now() - interval '20 days') ON CONFLICT (id) DO NOTHING;
INSERT INTO cms.faq (id, question_en, question_ar, answer_en, answer_ar, category, is_published, sort_order, created_at) VALUES ('2afbb222-a0f7-412d-a9dd-45332009ebde', 'Which Bahrain governorates and GCC destinations do you cover?', 'ما هي المحافظات في البحرين ووجهات الخليج التي تغطونها؟', 'We provide same-day and next-day fulfillment across Capital, Muharraq, Northern, and Southern Governorates, plus scheduled cross-border freight to Saudi Arabia, UAE, Qatar, Kuwait, and Oman.', 'نوفر التوصيل في نفس اليوم أو اليوم التالي في جميع محافظات البحرين، بالإضافة إلى الشحن المجدول لدول مجلس التعاون الخليجي.', 'logistics', true, 21, now() - interval '23 days') ON CONFLICT (id) DO NOTHING;
INSERT INTO cms.page (id, slug, page_type, title_en, title_ar, seo_title_en, seo_title_ar, seo_description_en, seo_description_ar, blocks, is_visible, in_header, in_footer, sort_order, created_at, updated_at) VALUES ('pg-home', 'home', 'home', 'Marina Heights', 'مارينا هايتس', 'Marina Heights | Waterfront Residences, Commercial Towers & Asset Management', 'مارينا هايتس | المساكن البحرية والأبراج التجارية وإدارة الأملاك', 'Licensed real estate brokerage and property management firm specializing in waterfront residential communities and Grade-A commercial leasing. Explore Marina Heights in Amwaj Islands.', 'شركة وساطة وإدارة عقارية مرخصة متخصصة في المجتمعات السكنية البحرية وتأجير المكاتب التجارية. تصفح صفحة مارينا هايتس.', '[{"id":"pg-home-hero","type":"hero","titleEn":"Marina Heights | Waterfront Residences, Commercial Towers & Asset Management","titleAr":"مارينا هايتس | المساكن البحرية والأبراج التجارية وإدارة الأملاك","image":"/api/files/media/banners/banner-01.png"},{"id":"pg-home-body","type":"rich_section","ctaEn":"Request Proposal","ctaAr":"طلب عرض سعر","sortOrder":1}]'::jsonb, true, true, false, 1, now() - interval '2160 hours', now()) ON CONFLICT (id) DO NOTHING;
